const KEY='lvjian-guide-v1';
let state={view:'intro',step:0,max:0,answers:{},extra:{},draft:null,confirmed:false};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.answers)state={...state,...saved};}catch{}
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const a=()=>state.answers;
const stages=['还没有开始','已经在做，咨询不精准','已有咨询，希望增加委托'];
const labels=['你的起点','执业与业务','想服务的人','值得信任的理由','你的目标'];
let bank=window.QUESTION_BANK||[];
function save(){try{localStorage.setItem(state.demo?KEY+'-demo':KEY,JSON.stringify(state));document.querySelector('#save').textContent='已保存在此浏览器';}catch{document.querySelector('#save').textContent='未能保存，请导出备份';}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',2800);}
function field(id,label,placeholder='',type='text',optional=false){return `<div class="field"><label for="${id}">${label}${optional?'<span class="optional">选填，可稍后补充</span>':''}</label>${type==='textarea'?`<textarea id="${id}" data-key="${id}" placeholder="${esc(placeholder)}">${esc(a()[id])}</textarea>`:`<input id="${id}" data-key="${id}" type="${type}" ${type==='number'?'min="0" max="80" step="1"':''} value="${esc(a()[id])}" placeholder="${esc(placeholder)}">`}</div>`;}
function chips(id,items,max=1){return `<div class="choices">${items.map(t=>`<button type="button" class="choice ${(Array.isArray(a()[id])?a()[id].includes(t):a()[id]===t)?'selected':''}" data-choice="${id}" data-value="${esc(t)}" data-max="${max}" aria-pressed="${Array.isArray(a()[id])?a()[id].includes(t):a()[id]===t}">${esc(t)}</button>`).join('')}</div>`;}
function go(view){state.view=view;save();render();window.scrollTo(0,0);}
function intro(){app.innerHTML=`<main class="intro"><section><span class="eyebrow">从你的真实经历出发</span><h1>让合适的客户，<br>看见你的<em>专业价值。</em></h1><p class="lead">先聊聊你的业务、客户和经历，形成一份属于你的定位草稿。其他资料，我们之后慢慢补。</p><button class="primary" id="start">${state.max||a().stage?'继续我的填写':'开始梳理我的定位'}</button>${state.draft?'<button class="quiet" id="see-result">查看已有草稿</button>':''}<div class="benefits"><span>5 个小主题</span><span>随时离开，随时继续</span></div><p class="small">填写内容仅保存在当前浏览器。换设备前，请导出备份。</p></section><aside class="sample"><div class="sample-head"><span class="small" style="color:#ccd7eb">你将得到这样的定位草稿 · 示例</span><h2>有方向，也有依据。</h2><span>聚焦劳动争议，服务职场中的关键决定</span></div><div class="sample-body"><dl><dt>优先服务的人</dt><dd>面临离职协商与劳动争议的职场人</dd><dt>让客户信任的依据</dt><dd>从你讲述的真实经历中整理，交由你确认。</dd><dt>可以开始的内容</dt><dd>「收到解除通知后，先确认哪几件事？」</dd></dl><span class="pill">可编辑</span> <span class="pill">可逐步完善</span></div></aside></main><section class="journey"><div><b>先说你知道的</b><p>不必先想清楚自己的“差异化优势”。</p></div><div><b>先拿到一份草稿</b><p>把业务、人群与经历放在一起看。</p></div><div><b>再补充有用的资料</b><p>案例、表达样本和经营数据，按需填写。</p></div></section>`;document.querySelector('#start').onclick=()=>go('wizard');document.querySelector('#see-result')?.addEventListener('click',()=>go('result'));}
function wizard(){let content='',title='',desc='',tip='';const s=state.step;
if(s===0){title='先从你现在的状态开始';desc='我们会根据你的情况，调整后面的问题。';tip='没有运营过账号也没关系。专业定位可以从你已经做过的事情开始。';content=`<div class="field"><label>你目前处于哪个阶段？</label>${stages.map((t,i)=>`<button class="stage-choice ${a().stage===t?'selected':''}" data-choice="stage" data-value="${t}" data-max="1" aria-pressed="${a().stage===t}"><strong>${t}</strong><small>${['先明确业务方向，找到适合自己的表达起点','让内容吸引更匹配的客户','梳理服务和信任依据，让咨询更有质量'][i]}</small></button>`).join('')}</div>`;}
if(s===1){title='你在哪里，擅长处理什么？';desc='区分现在常做的业务，以及接下来想重点发展的方向。';tip='写“离婚财产分割”会比“民商事”更具体。先写一个你熟悉的方向就好。';content=`<div class="row">${field('city','主要执业城市','例如：杭州')}${field('years','执业年限','例如：5','number',true)}</div><div class="field"><label>目前常做的业务 <span class="optional">最多选 3 项</span></label>${chips('areas',['婚姻家事','劳动争议','公司与股权','刑事辩护','合同纠纷','知识产权','房产与建设工程','其他'],3)}</div>${(a().areas||[]).includes('其他')?field('otherArea','其他业务','写下你的业务领域'):''}${field('priority','接下来最想发展的具体业务','例如：离婚财产分割、劳动仲裁，建议 1—2 项')}`;}
if(s===2){title='你希望谁来找到你？';desc='想一位你希望再次遇到的客户，描述他所处的具体情境。';tip='不需要写姓名。身份、遇到的事情和一句原话，往往就足够具体。';content=field('client','你最希望服务哪类客户？','例如：正在协商离职、担心补偿不合理的职场人','textarea')+field('question','他们最常问的一句话是什么？','例如：公司让我签这个协议，我该先看什么？','textarea',true)+field('excluded','有哪些明确不想承接的业务？','没有也可以留空','text',true);}
if(s===3){title='讲一件你真正做过的事';desc='不必写成宣传文案，一小段真实经历就很好。';tip='这里的内容会成为定位草稿的信任依据。暂时跳过时，我们会明确标记“待补充”，不会编造经历。';content=field('story','有没有一次，你帮助客户解决了具体问题？','对方遇到什么问题？你做了什么？有什么客观进展？\n也可以写一段与业务相关的行业经历。','textarea',true)+`<p class="small">请勿填写当事人姓名、联系方式或非公开案件秘密。内容仅供梳理，公开使用前仍需确认权限。</p>`;}
if(s===4){title='这次，你最希望改变什么？';desc='先明确一个目标，让接下来的内容有方向。';tip='目标可以随着实际咨询反馈调整。它是一份可验证的起点，不是永久标签。';content=`<div class="field"><label>最希望达成的目标</label>${chips('goal',['获得更精准的咨询','获得更想承接的案件','提升专业知名度','建立长期个人品牌'])}</div>`;if(a().stage===stages[0])content+=`<div class="field"><label>每周能投入多少时间？ <span class="optional">选填</span></label>${chips('time',['1小时以内','1—2小时','3—5小时','有团队协助'])}</div>`;else if(a().stage===stages[1])content+=field('pain','目前咨询与预期的差距是什么？','例如：总是收到非主营业务咨询，或客户不在服务区域','textarea',true);else content+=field('service','最希望推广哪项收费服务？','例如：劳动合同审查、离职协商咨询','text',true);}
app.innerHTML=`<main class="workspace"><nav class="steps" aria-label="填写步骤"><p>你的定位之旅</p>${labels.map((t,i)=>`<button class="step ${s===i?'active':i<s?'done':''}" data-step="${i}" ${i>state.max?'disabled':''} ${s===i?'aria-current="step"':''}><span>${i<s?'✓':i+1}</span>${t}</button>`).join('')}<p style="margin-top:35px">完成核心问题后<br>即可查看定位草稿</p></nav><section class="form-panel"><div class="progress" role="progressbar" aria-label="主题进度" aria-valuenow="${s+1}" aria-valuemin="0" aria-valuemax="5"><i style="width:${(s+1)*20}%"></i></div><span class="eyebrow">主题 ${s+1} / 5 · ${labels[s]}</span><h1 tabindex="-1">${title}</h1><p class="lead">${desc}</p><form id="form" novalidate>${content}<div class="error" role="alert" id="error"></div><div class="actions"><button type="button" id="back">${s===0?'返回首页':'上一个主题'}</button><button class="primary" type="submit">${s===4?'生成我的定位草稿':s===3&&!a().story?'暂时跳过，继续':'保存并继续'}</button></div></form></section><aside class="aside"><span class="eyebrow">填写小提示</span><h3>先真实，再清晰。</h3><p>${tip}</p><blockquote>你提供经历，<br>我们帮你把线索整理在一起。</blockquote><p class="small">内容自动保存在此浏览器，可以随时回来修改。</p></aside></main>`;
bind();document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.step=+b.dataset.step;go('wizard')});document.querySelector('#back').onclick=()=>{if(!s)go('intro');else{state.step--;go('wizard')}};document.querySelector('#form').onsubmit=e=>{e.preventDefault();let error='';if(s===0&&!a().stage)error='请选择当前阶段。';if(s===1){if(!a().city?.trim()||!a().priority?.trim()||!a().areas?.length)error='请填写城市、常做业务和优先发展的业务。';else if(a().years&&(Number(a().years)<0||Number(a().years)>80||!Number.isInteger(Number(a().years))))error='执业年限请填写0—80之间的整数。';else if(a().areas.includes('其他')&&!a().otherArea?.trim())error='请补充你的其他业务领域。';}if(s===2&&!a().client?.trim())error='请简单描述你希望服务的客户。';if(s===4&&!a().goal)error='请选择一个希望达成的目标。';if(error){document.querySelector('#error').textContent=error;return;}if(s===4){makeDraft();go('result');}else{state.step++;state.max=Math.max(state.max,state.step);go('wizard');}};}
function bind(){document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{a()[el.dataset.key]=el.value;state.confirmed=false;save();});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const {choice:k,value:v,max}=b.dataset;if(+max===1)a()[k]=v;else{let selected=a()[k]||[];if(selected.includes(v))selected=selected.filter(x=>x!==v);else if(selected.length<+max)selected=[...selected,v];else return toast(`最多选择 ${max} 项`);a()[k]=selected;}state.confirmed=false;save();wizard();});}
function makeDraft(){const x=a();const generated={position:`在${x.city}，围绕${x.priority}，为${x.client}提供法律服务。`,client:x.client,evidence:x.story?.trim()||'待补充：添加一段真实经历后，再确认信任依据。',topics:[x.question||`${x.priority}：客户通常需要先确认哪些信息？`,`${x.priority}：正式咨询前，可以准备哪些材料？`,`${x.priority}：哪些情况值得尽早咨询律师？`].join('\n')};if(!state.draft)state.draft=generated;else for(const k of Object.keys(generated))if(!state.edited?.[k])state.draft[k]=generated[k];state.confirmed=false;save();}
function result(){if(!state.draft){go('wizard');return;}const d=state.draft;app.innerHTML=`<main class="result"><div class="result-top"><div><span class="eyebrow">你的专业定位 · 草稿</span><h1>方向，开始清晰了。</h1><p class="muted">这是一份起点。请核对事实，把不符合你的表达改掉。</p></div><button id="edit-core">修改核心回答</button></div><section class="profile"><div class="profile-title"><small>定位表达 · 根据你的回答整理，待你确认</small><label for="d-position" class="small" style="display:block;color:white">一句话介绍你的方向</label><textarea id="d-position" data-draft="position">${esc(d.position)}</textarea></div><div class="result-grid">${[['client','目标客户','来自你的填写'],['evidence','信任依据','来自你的经历；未填写则保持待补充'],['topics','初始内容选题','模板建议，需结合真实业务核对']].map(([k,t,sub])=>`<div class="field"><label for="d-${k}">${t}</label><small>${sub}</small><textarea id="d-${k}" data-draft="${k}">${esc(d[k])}</textarea></div>`).join('')}<div class="field"><label>你的业务边界</label><p>${esc(a().excluded||'暂未设置，可在核心回答中补充。')}</p><span class="pill">目标：${esc(a().goal)}</span><p class="small">草稿由填写内容与固定模板整理，不代表经过市场验证的定位结论。</p></div></div></section><div class="actions"><button class="quiet" id="download">下载我的资料</button><button class="primary" id="confirm">${state.confirmed?'已确认这份草稿':'确认这份草稿'}</button></div><section class="supplement"><h2>下一步，补一点更有用的。</h2><p class="muted">按你现在最需要的部分填写，不必一次完成。</p><div class="modules">${[['证据','让专业更有依据','补充职业经历、代表事项与素材权限。',3],['表达','让内容更像你','补充表达习惯、兴趣与自然表达样本。',8],['业务','让获客更有方向','补充服务产品、客户顾虑与经营数据。',6]].map(([k,t,sub,step])=>`<button class="module" data-open="${step}"><span class="count">${k}</span><b>${t}</b><small>${sub}</small><small style="margin-top:16px;color:var(--blue)">进入补充</small></button>`).join('')}</div><button class="quiet" id="all" style="margin-top:18px">查看全部补充资料</button></section></main>`;document.querySelectorAll('[data-draft]').forEach(el=>el.oninput=()=>{state.draft[el.dataset.draft]=el.value;state.edited={...state.edited,[el.dataset.draft]:true};state.confirmed=false;document.querySelector('#confirm').textContent='确认这份草稿';save();});document.querySelector('#edit-core').onclick=()=>{state.step=0;go('wizard')};document.querySelector('#confirm').onclick=()=>{state.confirmed=true;save();result();toast('草稿已确认并保存。仍可随时修改。')};document.querySelector('#download').onclick=download;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.openGroup=+b.dataset.open;go('library')});document.querySelector('#all').onclick=()=>{state.openGroup=0;go('library')};}
const supplementSections={3:{title:"让专业更有依据",groups:[2,3],description:"补充职业经历、代表事项与素材权限，让你的专业优势有真实依据。"},8:{title:"让内容更像你",groups:[7,8],description:"补充兴趣、表达习惯与自然表达样本，找到适合你的内容方式。"},6:{title:"让获客更有方向",groups:[4,5,6,9],description:"梳理业务选择、目标客户、服务产品和获客目标。"}};
function library(){const section=supplementSections[state.openGroup];const groups=section?section.groups:[...new Set(bank.filter(r=>r[1]<11).map(r=>r[1]))];app.innerHTML=`<main class="library"><button id="return">返回定位草稿</button><h1>${section?section.title:"全部补充资料"}</h1><p class="muted">${section?section.description:"按分类查看全部资料，选择需要完善的部分。"} 每一项都可稍后再填，离开时自动保存。</p><p class="small">补充资料不会自动改写已确认的草稿；可返回结果页手动调整。案例及经历可在同一输入框分段填写多条。</p>${groups.map(g=>`<details ${section&&g===groups[0]?'open':''}><summary>${esc(bank.find(r=>r[1]===g)[2])} <span class="optional">${bank.filter(r=>r[1]===g).length} 项</span></summary>${bank.filter(r=>r[1]===g).map(r=>extraField(r)).join('')}</details>`).join('')}<p class="export-note">所有资料保存在当前浏览器，建议完成后导出一份备份。</p><button class="primary" id="download">导出全部填写内容</button></main>`;document.querySelector('#return').onclick=()=>go('result');document.querySelector('#download').onclick=download;document.querySelectorAll('[data-extra]').forEach(el=>el.oninput=()=>{state.extra[el.dataset.extra]=el.value;save()});}
function extraField(r){const id=r[0],options=r[7]?r[7].split('；'):[];let input;if(r[5]==='单选')input=`<select id="e-${id}" data-extra="${id}"><option value="">暂不填写</option>${options.map(o=>`<option ${state.extra[id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else input=`<textarea id="e-${id}" data-extra="${id}" placeholder="${options.length?'可填写上方选项，并补充说明':'在这里填写；多条经历或事项可分段记录'}">${esc(state.extra[id]||'')}</textarea>`;return `<div class="field"><label for="e-${id}">${esc(r[4])}<span class="optional">${id}</span></label><small>${esc(r[8])}</small>${options.length&&r[5]!=='单选'?`<p class="small">可选内容：${esc(r[7])}</p>`:''}${input}</div>`;}
function download(){const data={example:!!state.demo,version:1,exportedAt:new Date().toISOString(),core:state.answers,draft:state.draft,confirmed:state.confirmed,supplement:bank.filter(r=>state.extra[r[0]]).map(r=>({id:r[0],category:r[2],question:r[4],answer:state.extra[r[0]]}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=state.demo?'律见-虚构示例资料.json':'律见-我的定位资料.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('资料已导出，可作为本地备份。');}
function render(){const banner=document.querySelector('#example-bar');banner.hidden=!state.demo;banner.innerHTML=state.demo?'<span><b>虚构示例 · 林律师</b> 人物、案例、价格及经营数据均为演示，不能作为真实业绩。</span><button id="leave-demo">退出示例，返回我的填写</button>':'';document.querySelector('#leave-demo')?.addEventListener('click',leaveDemo);if(state.view==='wizard')wizard();else if(state.view==='result')result();else if(state.view==='library')library();else intro();}
document.querySelector('#home').onclick=e=>{e.preventDefault();go('intro')};document.querySelector('#export').onclick=download;render();

function leaveDemo(){let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY));}catch{}state=saved||{view:'intro',step:0,max:0,answers:{},extra:{},draft:null,confirmed:false};render();window.scrollTo(0,0);toast('已返回你的填写内容。');}
document.querySelector('#demo').onclick=()=>{if(!state.demo)save();state=structuredClone(window.LVJIAN_DEMO);save();render();window.scrollTo(0,0);toast('已载入虚构示例，你的原有填写保持不变。');};
